mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 2.0;
  vec2 t = abs(p.xy) - vec2(1.6, 1.2);
  float tun = -max(t.x, t.y);
  float rings = length(vec2(length(p.xy) - 1.5, mod(p.z, 2.0) - 1.0)) - 0.1;
  return min(-tun, rings);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.01 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 15.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.01, 0.02, 0.04);
  if (t < 15.0) {
    vec3 pos = ro + rd * t;
    float fog = 1.0 / (1.0 + t * t * 0.02);
    vec3 neon = mix(vec3(0.0, 0.8, 1.0), vec3(1.0, 0.2, 0.6), sin(pos.z * 0.5) * 0.5 + 0.5);
    col = neon * fog * 1.5;
  }
  col += glow * vec3(0.1, 0.9, 1.1) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
